namespace
{
    /** How a jump (ResumeAt) is written in a save's choice path. */
    const FString JumpMark = FString(TEXT("\u2192"));

    bool Listed(const TCHAR* const* List, int32 Num, const FString& Name)
    {
        for (int32 i = 0; i < Num; ++i)
            if (Name == List[i]) return true;
        return false;
    }

    bool IsPassage(const FString& Name) { return Listed(NarrativeBridgeStoryInfo::Passages, NarrativeBridgeStoryInfo::NumPassages, Name); }
    bool IsLine(const FString& Name) { return Listed(NarrativeBridgeStoryInfo::Lines, NarrativeBridgeStoryInfo::NumLines, Name); }

    /** The passage a start point is in: the name itself, or the passage of a line ("garden" for "garden.line_…"). */
    FString PassageOfName(const FString& Name)
    {
        int32 Dot = INDEX_NONE;
        return Name.FindChar(TEXT('.'), Dot) ? Name.Left(Dot) : Name;
    }

    /**
     * The Ink path to choose for a start point. A line is reached through its entry knot, "passage__line_…", which
     * diverts to the line's label (a label after a Continue break sits inside the weave, where a path can't name it).
     */
    FString InkPathOf(const FString& Name) { return IsLine(Name) ? Name.Replace(TEXT("."), TEXT("__")) : Name; }
    bool IsItemVariable(const FString& Name) { return Listed(NarrativeBridgeStoryInfo::ItemVariables, NarrativeBridgeStoryInfo::NumItemVariables, Name); }
    bool IsStoryVariable(const FString& Name) { return Listed(NarrativeBridgeStoryInfo::Variables, NarrativeBridgeStoryInfo::NumVariables, Name); }

    FString KnotOf(const FString& Path)
    {
        if (Path.IsEmpty()) return FString();
        FString Knot = Path;
        int32 Dot = INDEX_NONE;
        if (Path.FindChar(TEXT('.'), Dot)) Knot = Path.Left(Dot);
        return IsPassage(Knot) ? Knot : FString();
    }

    /** A name and value from a tag ("music:calm" → "music", "calm"). */
    void SplitTag(const FString& Raw, FString& Name, FString& Value)
    {
        const FString Tag = Raw.TrimStartAndEnd();
        Name = Tag;
        Value.Reset();
        int32 Colon = INDEX_NONE;
        if (Tag.FindChar(TEXT(':'), Colon))
        {
            Name = Tag.Left(Colon).TrimStartAndEnd();
            Value = Tag.Mid(Colon + 1).TrimStartAndEnd();
        }
    }

    bool IsStoryTag(const FString& Tag)
    {
        FString Name, Value;
        SplitTag(Tag, Name, Value);
        return Listed(NarrativeBridgeStoryInfo::ReservedTags, NarrativeBridgeStoryInfo::NumReservedTags, Name);
    }

    FString ValueAsString(const FInkpotValue& Value)
    {
        if (UInkpotValueLibrary::IsInkpotValueBool(Value)) return UInkpotValueLibrary::InkpotValueAsBool(Value) ? TEXT("true") : TEXT("false");
        if (UInkpotValueLibrary::IsInkpotValueInt(Value)) return FString::FromInt(UInkpotValueLibrary::InkpotValueAsInt(Value));
        if (UInkpotValueLibrary::IsInkpotValueFloat(Value)) return FString::SanitizeFloat(UInkpotValueLibrary::InkpotValueAsFloat(Value));
        if (UInkpotValueLibrary::IsInkpotValueString(Value)) return UInkpotValueLibrary::InkpotValueAsString(Value);
        return FString();
    }

    bool Ordered(const FString& Op, int32 C)
    {
        if (Op == TEXT("==")) return C == 0;
        if (Op == TEXT("!=")) return C != 0;
        if (Op == TEXT("<")) return C < 0;
        if (Op == TEXT("<=")) return C <= 0;
        if (Op == TEXT(">")) return C > 0;
        if (Op == TEXT(">=")) return C >= 0;
        return false;
    }

    /** Reads the story's variables for the conditions of locked choices (NarrativeBridgeStoryInfo::GatedChoices), the way ink compares them. */
    class FInkpotReader final : public NarrativeBridgeStoryInfo::FVariableReader
    {
    public:
        explicit FInkpotReader(UInkpotStory* InStory) : Story(InStory) {}

        virtual bool Has(const TCHAR* Name) const override
        {
            FInkpotValue V;
            if (!Read(Name, V)) return false;
            if (UInkpotValueLibrary::IsInkpotValueBool(V)) return UInkpotValueLibrary::InkpotValueAsBool(V);
            if (UInkpotValueLibrary::IsInkpotValueInt(V)) return UInkpotValueLibrary::InkpotValueAsInt(V) != 0;
            if (UInkpotValueLibrary::IsInkpotValueFloat(V)) return UInkpotValueLibrary::InkpotValueAsFloat(V) != 0.f;
            return false;
        }

        virtual bool CompareNumber(const TCHAR* Name, const TCHAR* Op, double Value) const override
        {
            FInkpotValue V;
            const FString O = Op;
            if (!Read(Name, V)) return O == TEXT("!=");
            double X = 0;
            if (UInkpotValueLibrary::IsInkpotValueInt(V)) X = UInkpotValueLibrary::InkpotValueAsInt(V);
            else if (UInkpotValueLibrary::IsInkpotValueFloat(V)) X = UInkpotValueLibrary::InkpotValueAsFloat(V);
            else if (UInkpotValueLibrary::IsInkpotValueBool(V))
            {
                // Ink compares true/false with a number as 1/0, for == and != only.
                const bool B = UInkpotValueLibrary::InkpotValueAsBool(V);
                return O == TEXT("==") ? B == (Value != 0) : O == TEXT("!=") ? B != (Value != 0) : false;
            }
            else return O == TEXT("!=");
            return Ordered(O, X < Value ? -1 : X > Value ? 1 : 0);
        }

        virtual bool CompareText(const TCHAR* Name, const TCHAR* Op, const TCHAR* Value) const override
        {
            FInkpotValue V;
            const FString O = Op;
            if (!Read(Name, V) || !UInkpotValueLibrary::IsInkpotValueString(V)) return O == TEXT("!=");
            return Ordered(O, UInkpotValueLibrary::InkpotValueAsString(V).Compare(Value, ESearchCase::CaseSensitive));
        }

        virtual bool CompareBool(const TCHAR* Name, const TCHAR* Op, bool Value) const override
        {
            const bool B = Has(Name);
            const FString O = Op;
            return O == TEXT("==") ? B == Value : O == TEXT("!=") ? B != Value : false;
        }

    private:
        bool Read(const TCHAR* Name, FInkpotValue& Out) const
        {
            if (!Story || !Story->IsVariableDefined(Name)) return false;
            bool bOk = false;
            Story->GetValue(Name, Out, bOk);
            return bOk;
        }

        UInkpotStory* Story;
    };

    /** The choices on offer, from ink's state itself (Inkpot's own list only updates as the story continues). */
    TArray<TSharedPtr<Ink::FChoice>> InkChoices(UInkpotStory* Story)
    {
        if (!Story || !Story->GetStoryInternal().IsValid()) return {};
        return Story->GetStoryInternal()->GetCurrentChoices();
    }

    TMap<FString, TStrongObjectPtr<UTexture2D>>& Pictures()
    {
        static TMap<FString, TStrongObjectPtr<UTexture2D>> Loaded;
        return Loaded;
    }

    FString SlotKey(int32 Slot) { return Slot == UNarrativeBridgeComponent::AutosaveSlot ? FString(TEXT("autosave")) : Slot < 0 ? FString(TEXT("quicksave")) : FString::Printf(TEXT("slot-%d"), Slot); }
    FString SaveFile(const FString& Key) { return FPaths::ProjectSavedDir() / TEXT("SaveGames/NarrativeBridge") / NarrativeBridgeStoryInfo::SaveFolder / Key + TEXT(".json"); }
    FString ChosenFile() { return FPaths::ProjectSavedDir() / TEXT("SaveGames/NarrativeBridge") / NarrativeBridgeStoryInfo::SaveFolder / TEXT("chosen.txt"); }

    /** How a choice is remembered once taken: its knot and its text as written ("harbour|Take the boat"). */
    FString ChosenKeyOf(const TSharedPtr<Ink::FChoice>& Choice)
    {
        FString Knot = Choice->GetSourcePath();
        int32 Dot = INDEX_NONE;
        if (Knot.FindChar(TEXT('.'), Dot)) Knot = Knot.Left(Dot);
        return Knot + TEXT("|") + Choice->GetText().TrimStartAndEnd();
    }
}

UNarrativeBridgeComponent::UNarrativeBridgeComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
    PrimaryComponentTick.bStartWithTickEnabled = true;
    // Voice clips go on while a Narrative Story Trigger pauses the game for the dialogue.
    PrimaryComponentTick.bTickEvenWhenPaused = true;
}

void UNarrativeBridgeComponent::BeginPlay()
{
    Super::BeginPlay();
    LanguageHandle = UNarrativeLocalization::OnChanged().AddUObject(this, &UNarrativeBridgeComponent::Relocalize);
    if (bStartOnBeginPlay) StartStory();
}

void UNarrativeBridgeComponent::EndPlay(const EEndPlayReason::Type Reason)
{
    UNarrativeLocalization::OnChanged().Remove(LanguageHandle);
    StopVoice();
    if (InkStory && GEngine)
        if (UInkpot* Pot = GEngine->GetEngineSubsystem<UInkpot>()) Pot->EndStory(InkStory);
    InkStory = nullptr;
    Super::EndPlay(Reason);
}

void UNarrativeBridgeComponent::StartStory()
{
    Begin(FString());
}

void UNarrativeBridgeComponent::StartAt(const FString& Passage)
{
    if (!IsStartPoint(Passage)) { ReportError(FString::Printf(TEXT("There is no passage or line called %s."), *Passage)); return; }
    Begin(Passage);
}

bool UNarrativeBridgeComponent::IsStartPoint(const FString& Name)
{
    return !Name.IsEmpty() && (IsPassage(Name) || IsLine(Name));
}

void UNarrativeBridgeComponent::EnterAt(const FString& Name)
{
    if (!InkStory) { StartAt(Name); return; }
    if (!IsStartPoint(Name)) { ReportError(FString::Printf(TEXT("There is no passage or line called %s."), *Name)); return; }
    const bool bExited = IsAtExit();
    // Saved as a jump, like ResumeAt, so a save carries over to a revised story.
    ChoicePath.Add(JumpMark + Name);
    Transcript.Reset();
    bHasEnded = false;
    LastPassage = PassageOfName(Name);
    SetStatus(FString());
    StopVoice();
    InkStory->ChoosePath(InkPathOf(Name));
    OnRestarted.Broadcast();
    if (bExited) OnResumed.Broadcast();
    Advance();
}

bool UNarrativeBridgeComponent::HasItem(const FString& ItemId) const
{
    if (UObject* Inventory = Authority()) return INarrativeInventoryAuthority::Execute_HasItem(Inventory, ItemId);
    const FString Var = TEXT("has_") + ItemId;
    if (!InkStory || !IsItemVariable(Var)) return false;
    bool bFound = false;
    const FInkpotValue Value = GetVariable(Var, bFound);
    return bFound && UInkpotValueLibrary::InkpotValueAsBool(Value);
}

void UNarrativeBridgeComponent::Begin(const FString& Passage)
{
    if (!StoryAsset) StoryAsset = LoadObject<UInkpotStoryAsset>(nullptr, NarrativeBridgeStoryInfo::StoryAssetPath, nullptr, LOAD_NoWarn | LOAD_Quiet);
    if (!StoryAsset)
    {
        ReportError(TEXT("No story asset. Open the project in the editor to import StorySource/MainStory.ink, or set Story Asset."));
        return;
    }
    UInkpot* Pot = GEngine ? GEngine->GetEngineSubsystem<UInkpot>() : nullptr;
    if (!Pot) { ReportError(TEXT("The Inkpot plugin isn't running.")); return; }
    InkStory = Pot->BeginStory(StoryAsset);
    if (!InkStory || !InkStory->IsValid())
    {
        InkStory = nullptr;
        ReportError(TEXT("Inkpot couldn't start the story."));
        return;
    }
    for (int32 i = 0; i < NarrativeBridgeStoryInfo::NumItemVariables + NarrativeBridgeStoryInfo::NumVariables; ++i)
    {
        const TCHAR* Name = i < NarrativeBridgeStoryInfo::NumItemVariables ? NarrativeBridgeStoryInfo::ItemVariables[i] : NarrativeBridgeStoryInfo::Variables[i - NarrativeBridgeStoryInfo::NumItemVariables];
        FOnInkpotVariableChange Observer;
        Observer.BindUFunction(this, GET_FUNCTION_NAME_CHECKED(UNarrativeBridgeComponent, HandleVariableChange));
        InkStory->SetOnVariableChange(Observer, Name);
    }
    ChoicePath.Reset();
    Transcript.Reset();
    bHasEnded = false;
    StartPassage = Passage;
    LastPassage = PassageOfName(Passage);
    LoadNote.Reset();
    SetStatus(FString());
    StopVoice();
    if (!Passage.IsEmpty()) InkStory->ChoosePath(InkPathOf(Passage));
    OnRestarted.Broadcast();
    Advance();
}

bool UNarrativeBridgeComponent::IsWaitingForContinue() const
{
    const TArray<TSharedPtr<Ink::FChoice>> Choices = InkChoices(InkStory);
    return Choices.Num() == 1 && Choices[0]->GetText() == NarrativeBridgeStoryInfo::ContinueText;
}

FString UNarrativeBridgeComponent::GetCurrentExit() const
{
    const TArray<TSharedPtr<Ink::FChoice>> Choices = InkChoices(InkStory);
    if (Choices.Num() != 1) return FString();
    const FString Text = Choices[0]->GetText();
    return Text.StartsWith(NarrativeBridgeStoryInfo::ExitPrefix, ESearchCase::CaseSensitive) ? Text.Mid(FCString::Strlen(NarrativeBridgeStoryInfo::ExitPrefix)) : FString();
}

TArray<FString> UNarrativeBridgeComponent::GetSourceChoices() const
{
    TArray<FString> Labels;
    if (IsWaitingForContinue() || IsAtExit()) return Labels;
    for (const TSharedPtr<Ink::FChoice>& Choice : InkChoices(InkStory)) Labels.Add(Choice->GetText());
    return Labels;
}

TArray<FString> UNarrativeBridgeComponent::GetChoices() const
{
    TArray<FString> Labels = GetSourceChoices();
    for (FString& Label : Labels) Label = UNarrativeLocalization::Translate(Label);
    return Labels;
}

FString UNarrativeBridgeComponent::GetCurrentPassage() const
{
    const TArray<TSharedPtr<Ink::FChoice>> Choices = InkChoices(InkStory);
    if (Choices.Num() > 0)
    {
        const FString Knot = KnotOf(Choices[0]->GetSourcePath());
        if (!Knot.IsEmpty()) return Knot;
    }
    return LastPassage;
}

TArray<FNarrativeLockedChoice> UNarrativeBridgeComponent::GetLockedChoices() const
{
    TArray<FNarrativeLockedChoice> Locked;
    const TArray<TSharedPtr<Ink::FChoice>> Choices = InkChoices(InkStory);
    if (!InkStory || bHasEnded || Choices.Num() == 0 || IsAtExit() || IsWaitingForContinue()) return Locked;
    const FString Passage = GetCurrentPassage();
    auto Offered = [&Choices](const TCHAR* Text) { return Choices.ContainsByPredicate([Text](const TSharedPtr<Ink::FChoice>& C) { return C->GetText() == Text; }); };
    // While a forced choice is on offer, it's the only way on: nothing is shown as locked.
    for (int32 i = 0; i < NarrativeBridgeStoryInfo::NumGatedChoices; ++i)
    {
        const NarrativeBridgeStoryInfo::FGatedChoice& G = NarrativeBridgeStoryInfo::GatedChoices[i];
        if (G.bForced && Passage == G.Passage && Offered(G.Text)) return Locked;
    }
    const FInkpotReader Reader(InkStory);
    for (int32 i = 0; i < NarrativeBridgeStoryInfo::NumGatedChoices; ++i)
    {
        const NarrativeBridgeStoryInfo::FGatedChoice& G = NarrativeBridgeStoryInfo::GatedChoices[i];
        if (Passage != G.Passage || Offered(G.Text)) continue;
        TArray<FString> Missing;
        for (int32 r = 0; r < G.NumRequirements; ++r)
            if (!G.Requirements[r].Test(Reader)) Missing.Add(UNarrativeLocalization::Translate(G.Requirements[r].Words));
        if (Missing.Num() == 0) continue;
        FNarrativeLockedChoice L;
        L.Text = UNarrativeLocalization::Translate(G.Text);
        L.Needs = FString::Join(Missing, TEXT(", "));
        Locked.Add(L);
    }
    return Locked;
}

const TSet<FString>& UNarrativeBridgeComponent::Chosen() const
{
    if (!bChosenLoaded)
    {
        bChosenLoaded = true;
        TArray<FString> Keys;
        if (FFileHelper::LoadFileToStringArray(Keys, *ChosenFile()))
            for (const FString& K : Keys)
                if (!K.IsEmpty()) ChosenBefore.Add(K);
    }
    return ChosenBefore;
}

bool UNarrativeBridgeComponent::WasChosen(int32 Index) const
{
    const TArray<TSharedPtr<Ink::FChoice>> Choices = InkChoices(InkStory);
    if (!Choices.IsValidIndex(Index) || IsWaitingForContinue() || IsAtExit()) return false;
    return Chosen().Contains(ChosenKeyOf(Choices[Index]));
}

void UNarrativeBridgeComponent::ForgetChosen()
{
    Chosen();
    ChosenBefore.Reset();
    IFileManager::Get().Delete(*ChosenFile(), false, false, true);
}

void UNarrativeBridgeComponent::Choose(int32 Index)
{
    const TArray<TSharedPtr<Ink::FChoice>> Choices = InkChoices(InkStory);
    if (!Choices.IsValidIndex(Index)) return;
    const FString Text = Choices[Index]->GetText();
    // A Continue break or an exit leaves no trace in the transcript: the page simply goes on.
    if (!IsWaitingForContinue() && !IsAtExit())
    {
        const FString Key = ChosenKeyOf(Choices[Index]);
        if (!Chosen().Contains(Key))
        {
            ChosenBefore.Add(Key);
            FFileHelper::SaveStringArrayToFile(ChosenBefore.Array(), *ChosenFile());
        }
        FNarrativeLine Line;
        Line.Text = Line.SourceText = Text;
        Line.Tags.Add(TEXT("choice"));
        Line.bIsChoice = true;
        Transcript.Add(Localize(Line));
    }
    ChoicePath.Add(Text);
    InkStory->ChooseChoiceIndex(Choices[Index]->GetIndex());
    StopVoice();
    Advance();
}

void UNarrativeBridgeComponent::Continue()
{
    if (IsWaitingForContinue()) Choose(0);
}

void UNarrativeBridgeComponent::Resume()
{
    if (!IsAtExit()) return;
    OnResumed.Broadcast();
    Choose(0);
}

void UNarrativeBridgeComponent::ResumeAt(const FString& Passage)
{
    if (!InkStory) return;
    if (!IsStartPoint(Passage)) { ReportError(FString::Printf(TEXT("There is no passage or line called %s."), *Passage)); return; }
    const bool bExited = IsAtExit();
    // Saves record the jump, so a save carries over to a revised story too.
    ChoicePath.Add(JumpMark + Passage);
    InkStory->ChoosePath(InkPathOf(Passage));
    LastPassage = PassageOfName(Passage);
    bHasEnded = false;
    StopVoice();
    if (bExited) OnResumed.Broadcast();
    Advance();
}

void UNarrativeBridgeComponent::Advance()
{
    if (!InkStory) return;
    SyncFromAuthority();
    while (InkStory->CanContinue())
    {
        NotePassage();
        const FString Raw = InkStory->Continue().TrimStartAndEnd();
        const TArray<FString> Tags = InkStory->GetCurrentTags();
        if (!Raw.IsEmpty())
        {
            const FNarrativeLine Line = ParseLine(Raw, Tags);
            Transcript.Add(Line);
            QueueVoice(Line);
            OnLineShown.Broadcast(Line);
            OnLine.Broadcast(Line.Speaker, Line.Text, Line.Tags);
        }
        // A tag with no text after it (a cue at the end of a passage) still reaches the game.
        RaiseTags(Tags);
    }
    AutosaveIfNewPassage();
    Announce();
}

void UNarrativeBridgeComponent::Announce()
{
    if (IsAtExit()) OnExit.Broadcast(GetCurrentExit());
    else if (IsWaitingForContinue()) OnContinue.Broadcast();
    else if (InkChoices(InkStory).Num() > 0) OnChoices.Broadcast(GetChoices());
    else
    {
        bHasEnded = true;
        OnEnded.Broadcast();
    }
}

void UNarrativeBridgeComponent::RaiseTags(const TArray<FString>& Tags)
{
    for (const FString& Tag : Tags)
    {
        if (IsStoryTag(Tag)) continue;
        FString Name, Value;
        SplitTag(Tag, Name, Value);
        if (Name.IsEmpty()) continue;
        OnTag.Broadcast(Tag.TrimStartAndEnd());
        OnCue.Broadcast(Name, Value);
    }
}

void UNarrativeBridgeComponent::NotePassage()
{
    const FString Knot = KnotOf(InkStory->GetStoryInternal()->GetStoryState()->getCurrentPathString());
    if (!Knot.IsEmpty()) LastPassage = Knot;
}

FNarrativeLine UNarrativeBridgeComponent::ParseLine(const FString& Raw, const TArray<FString>& Tags) const
{
    FNarrativeLine Line;
    Line.Tags = Tags;
    for (const FString& Tag : Tags)
    {
        FString Name, Value;
        SplitTag(Tag, Name, Value);
        if (Name == TEXT("speaker")) Line.Speaker = Line.SpeakerId = Value;
        else if (Name == TEXT("scene")) Line.Scene = Value;
        else if (Name == TEXT("paren")) Line.Paren = Value;
        else if (Name == TEXT("image")) Line.Image = Value;
        else if (Name == TEXT("audio")) Line.VoiceClip = Value;
        else if (Name == TEXT("transition")) Line.bIsTransition = true;
        else if (Name == TEXT("cutscene")) Line.bIsCutscene = true;
    }
    Line.Text = Raw;
    if (!Line.Speaker.IsEmpty())
    {
        // Ink prints dialogue as "NAME: text"; the name shown is the one before the colon.
        FString Name, Text;
        if (Raw.Split(TEXT(": "), &Name, &Text, ESearchCase::CaseSensitive) && !Name.IsEmpty())
        {
            Line.Speaker = Name;
            Line.Text = Text;
        }
    }
    Line.SourceText = Line.Text;
    Line.SourceSpeaker = Line.Speaker;
    Line.SourceScene = Line.Scene;
    Line.SourceParen = Line.Paren;
    return Localize(Line);
}

FNarrativeLine UNarrativeBridgeComponent::Localize(FNarrativeLine Line)
{
    Line.Text = UNarrativeLocalization::Translate(Line.SourceText.IsEmpty() ? Line.Text : Line.SourceText);
    if (!Line.SourceSpeaker.IsEmpty()) Line.Speaker = UNarrativeLocalization::Translate(Line.SourceSpeaker);
    if (!Line.SourceScene.IsEmpty()) Line.Scene = UNarrativeLocalization::Translate(Line.SourceScene);
    if (!Line.SourceParen.IsEmpty()) Line.Paren = UNarrativeLocalization::Translate(Line.SourceParen);
    return Line;
}

void UNarrativeBridgeComponent::Relocalize()
{
    for (FNarrativeLine& Line : Transcript) Line = Localize(Line);
}

FString UNarrativeBridgeComponent::GetCurrentPicture() const
{
    for (int32 i = Transcript.Num() - 1; i >= 0; --i)
        if (!Transcript[i].Image.IsEmpty()) return Transcript[i].Image;
    return FString();
}

FString UNarrativeBridgeComponent::GetStoryVersion() const
{
    return NarrativeBridgeStoryInfo::StoryVersion;
}

// ---- Variables and inventory: the host game is the single source of truth -------------

FInkpotValue UNarrativeBridgeComponent::GetVariable(const FString& Name, bool& bFound) const
{
    FInkpotValue Value;
    bFound = false;
    if (!InkStory || (!IsStoryVariable(Name) && !IsItemVariable(Name)) || !InkStory->IsVariableDefined(Name)) return Value;
    InkStory->GetValue(Name, Value, bFound);
    return Value;
}

FString UNarrativeBridgeComponent::GetVariableAsString(const FString& Name) const
{
    bool bFound = false;
    const FInkpotValue Value = GetVariable(Name, bFound);
    return bFound ? ValueAsString(Value) : FString();
}

bool UNarrativeBridgeComponent::SetVariable(const FString& Name, const FInkpotValue& Value)
{
    if (!InkStory || !IsStoryVariable(Name)) return false;
    bool bOk = false;
    InkStory->SetValue(Name, Value, bOk);
    return bOk;
}

void UNarrativeBridgeComponent::SetItemOwned(const FString& ItemId, bool bOwned)
{
    if (!InkStory) return;
    bool bOk = false;
    InkStory->SetBool(FString(TEXT("has_")) + ItemId, bOwned, bOk);
}

void UNarrativeBridgeComponent::HandleVariableChange(UInkpotStory* ChangedStory, const FString& Variable, const FInkpotValue& NewValue)
{
    if (IsItemVariable(Variable) && !bSyncing)
    {
        if (UObject* Inventory = Authority())
        {
            const FString ItemId = Variable.Mid(4);
            if (UInkpotValueLibrary::IsInkpotValueBool(NewValue))
            {
                if (UInkpotValueLibrary::InkpotValueAsBool(NewValue)) INarrativeInventoryAuthority::Execute_GiveItem(Inventory, ItemId);
                else INarrativeInventoryAuthority::Execute_TakeItem(Inventory, ItemId);
            }
        }
    }
    if (!bSilent) OnVariableChanged.Broadcast(Variable, ValueAsString(NewValue));
}

void UNarrativeBridgeComponent::RaiseAllVariables()
{
    for (int32 i = 0; i < NarrativeBridgeStoryInfo::NumItemVariables; ++i) OnVariableChanged.Broadcast(NarrativeBridgeStoryInfo::ItemVariables[i], GetVariableAsString(NarrativeBridgeStoryInfo::ItemVariables[i]));
    for (int32 i = 0; i < NarrativeBridgeStoryInfo::NumVariables; ++i) OnVariableChanged.Broadcast(NarrativeBridgeStoryInfo::Variables[i], GetVariableAsString(NarrativeBridgeStoryInfo::Variables[i]));
}

UObject* UNarrativeBridgeComponent::Authority() const
{
    if (InventoryAuthority && InventoryAuthority->Implements<UNarrativeInventoryAuthority>()) return InventoryAuthority;
    if (AActor* Owner = GetOwner())
    {
        if (Owner->Implements<UNarrativeInventoryAuthority>()) return Owner;
        for (UActorComponent* C : Owner->GetComponents())
            if (C && C->Implements<UNarrativeInventoryAuthority>()) return C;
    }
    return nullptr;
}

void UNarrativeBridgeComponent::SyncFromAuthority()
{
    UObject* Inventory = Authority();
    if (!Inventory || !InkStory) return;
    bSyncing = true;
    for (int32 i = 0; i < NarrativeBridgeStoryInfo::NumItemVariables; ++i)
    {
        const FString Var = NarrativeBridgeStoryInfo::ItemVariables[i];
        bool bOk = false;
        InkStory->SetBool(Var, INarrativeInventoryAuthority::Execute_HasItem(Inventory, Var.Mid(4)), bOk);
    }
    bSyncing = false;
}

// ---- Saves, with story-version checks ----------------------------------------------------

FString UNarrativeBridgeComponent::Excerpt() const
{
    for (int32 i = Transcript.Num() - 1; i >= 0; --i)
    {
        const FNarrativeLine& L = Transcript[i];
        if (L.bIsChoice || L.Text.IsEmpty()) continue;
        const FString T = PlainText((L.Speaker.IsEmpty() ? FString() : L.Speaker + TEXT(": ")) + L.Text);
        return T.Len() > 90 ? T.Left(87) + TEXT("...") : T;
    }
    return FString();
}

FString UNarrativeBridgeComponent::SaveState() const
{
    if (!InkStory) return FString();
    TSharedRef<FJsonObject> Data = MakeShared<FJsonObject>();
    Data->SetStringField(TEXT("storyVersion"), NarrativeBridgeStoryInfo::StoryVersion);
    Data->SetStringField(TEXT("inkState"), InkStory->ToJSON());
    TArray<TSharedPtr<FJsonValue>> Path;
    for (const FString& C : ChoicePath) Path.Add(MakeShared<FJsonValueString>(C));
    Data->SetArrayField(TEXT("choicePath"), Path);
    Data->SetStringField(TEXT("startPassage"), StartPassage);
    Data->SetStringField(TEXT("savedAt"), FDateTime::UtcNow().ToIso8601());
    Data->SetStringField(TEXT("passage"), GetCurrentPassage());
    Data->SetStringField(TEXT("excerpt"), Excerpt());
    FString Out;
    const TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&Out);
    FJsonSerializer::Serialize(Data, Writer);
    return Out;
}

bool UNarrativeBridgeComponent::TryLoadState(const FString& Save, FString& Error)
{
    Error.Reset();
    LoadNote.Reset();
    TSharedPtr<FJsonObject> Data;
    if (!FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Save), Data) || !Data.IsValid()) { Error = TEXT("Save data is corrupt."); return false; }
    FString InkState;
    if (!Data->TryGetStringField(TEXT("inkState"), InkState) || InkState.IsEmpty()) { Error = TEXT("Save data is empty."); return false; }
    if (!InkStory) StartStory();
    if (!InkStory) { Error = TEXT("The story could not start."); return false; }
    FString Version;
    Data->TryGetStringField(TEXT("storyVersion"), Version);
    Data->TryGetStringField(TEXT("startPassage"), StartPassage);
    TArray<FString> Path;
    const TArray<TSharedPtr<FJsonValue>>* Saved = nullptr;
    const bool bHasPath = Data->TryGetArrayField(TEXT("choicePath"), Saved);
    if (bHasPath)
        for (const TSharedPtr<FJsonValue>& V : *Saved) Path.Add(V->AsString());
    if (Version != NarrativeBridgeStoryInfo::StoryVersion)
    {
        // Saves from before choices were recorded can't be carried over.
        if (!bHasPath)
        {
            Error = FString::Printf(TEXT("This save was made with story version %s but the game now has %s. Restart the narrative."), *Version, NarrativeBridgeStoryInfo::StoryVersion);
            return false;
        }
        ReplayChoices(Path, Version);
        return true;
    }
    InkStory->LoadJSON(InkState);
    ChoicePath = Path;
    Transcript.Reset();
    bHasEnded = false;
    Data->TryGetStringField(TEXT("passage"), LastPassage);
    StopVoice();
    OnRestarted.Broadcast();
    RaiseAllVariables();
    if (InkStory->CanContinue()) Advance();
    else Announce();
    return true;
}

// A save from another version of the story: play the new version from the start (or the passage it was started at),
// silently, making the same choices (matched by their text), so its text and variables apply. Stops at the first choice
// the new version no longer offers.
void UNarrativeBridgeComponent::ReplayChoices(const TArray<FString>& Path, const FString& SavedVersion)
{
    InkStory->ResetState();
    if (IsStartPoint(StartPassage)) InkStory->ChoosePath(InkPathOf(StartPassage));
    ChoicePath.Reset();
    Transcript.Reset();
    bHasEnded = false;
    LastPassage = PassageOfName(StartPassage);
    StopVoice();
    int32 Followed = 0;
    // The host's inventory is already where the save left it.
    bSyncing = true;
    bSilent = true;
    for (int32 i = 0, Steps = 0; i < Path.Num() && Steps < 10000; ++Steps)
    {
        const FString Before = InkStory->ToJSON();
        while (InkStory->CanContinue())
        {
            NotePassage();
            InkStory->Continue();
        }
        if (Path[i].StartsWith(JumpMark, ESearchCase::CaseSensitive))
        {
            // A jump the game made with ResumeAt.
            const FString Target = Path[i].Mid(JumpMark.Len());
            if (!IsStartPoint(Target)) break;
            InkStory->ChoosePath(InkPathOf(Target));
            LastPassage = PassageOfName(Target);
            ChoicePath.Add(Path[i]);
            ++Followed;
            ++i;
            continue;
        }
        const TArray<TSharedPtr<Ink::FChoice>> Choices = InkChoices(InkStory);
        const FString& Wanted = Path[i];
        const TSharedPtr<Ink::FChoice>* Match = Choices.FindByPredicate([&Wanted](const TSharedPtr<Ink::FChoice>& C) { return C->GetText() == Wanted; });
        if (Match)
        {
            InkStory->ChooseChoiceIndex((*Match)->GetIndex());
            ChoicePath.Add(Wanted);
            ++Followed;
            ++i;
        }
        else if (IsWaitingForContinue())
        {
            // A Continue break added since the save: take it.
            InkStory->ChooseChoiceIndex(0);
            ChoicePath.Add(NarrativeBridgeStoryInfo::ContinueText);
        }
        else if (Wanted == NarrativeBridgeStoryInfo::ContinueText)
        {
            // A Continue break removed since the save: skip it.
            ++Followed;
            ++i;
        }
        else
        {
            InkStory->LoadJSON(Before);
            break;
        }
    }
    bSyncing = false;
    bSilent = false;
    OnRestarted.Broadcast();
    RaiseAllVariables();
    LoadNote = Followed == Path.Num()
        ? FString::Printf(TEXT("Carried this save over from story version %s: all %d choices replayed."), *SavedVersion, Path.Num())
        : FString::Printf(TEXT("Carried this save over from story version %s: %d of %d choices still exist, so it resumes after the last one that does."), *SavedVersion, Followed, Path.Num());
    Advance();
}

bool UNarrativeBridgeComponent::ReadSlot(int32 Slot, FString& Data) const
{
    Data.Reset();
    if (SaveStorage && SaveStorage->Implements<UNarrativeSaveStorage>()) return INarrativeSaveStorage::Execute_ReadSave(SaveStorage, SlotKey(Slot), Data) && !Data.IsEmpty();
    return FFileHelper::LoadFileToString(Data, *SaveFile(SlotKey(Slot)), FFileHelper::EHashOptions::None, FILEREAD_Silent) && !Data.IsEmpty();
}

void UNarrativeBridgeComponent::WriteSlot(int32 Slot, const FString& Data)
{
    if (SaveStorage && SaveStorage->Implements<UNarrativeSaveStorage>()) { INarrativeSaveStorage::Execute_WriteSave(SaveStorage, SlotKey(Slot), Data); return; }
    // Write a new file and swap it in, so a crash mid-save never leaves half a save.
    const FString File = SaveFile(SlotKey(Slot));
    const FString Temp = File + TEXT(".tmp");
    if (!FFileHelper::SaveStringToFile(Data, *Temp, FFileHelper::EEncodingOptions::ForceUTF8WithoutBOM) || !IFileManager::Get().Move(*File, *Temp, true))
        ReportError(FString::Printf(TEXT("Could not save to %s."), *File));
}

void UNarrativeBridgeComponent::SaveToSlot(int32 Slot)
{
    if (!InkStory) return;
    WriteSlot(Slot, SaveState());
    if (Slot != AutosaveSlot) SetStatus(FString::Printf(TEXT("Saved to slot %d."), Slot));
    OnSaved.Broadcast(Slot);
}

bool UNarrativeBridgeComponent::LoadFromSlot(int32 Slot)
{
    FString Data;
    if (!ReadSlot(Slot, Data)) { SetStatus(TEXT("That slot is empty.")); return false; }
    FString Error;
    const bool bOk = TryLoadState(Data, Error);
    SetStatus(bOk ? (LoadNote.IsEmpty() ? (Slot == AutosaveSlot ? FString(TEXT("Loaded the autosave.")) : FString::Printf(TEXT("Loaded slot %d."), Slot)) : LoadNote) : Error);
    AutosavedPassage = GetCurrentPassage();
    return bOk;
}

void UNarrativeBridgeComponent::DeleteSlot(int32 Slot)
{
    if (SaveStorage && SaveStorage->Implements<UNarrativeSaveStorage>()) INarrativeSaveStorage::Execute_DeleteSave(SaveStorage, SlotKey(Slot));
    else IFileManager::Get().Delete(*SaveFile(SlotKey(Slot)), false, false, true);
}

FNarrativeSlotInfo UNarrativeBridgeComponent::GetSlot(int32 Slot) const
{
    FNarrativeSlotInfo Info;
    Info.Slot = Slot;
    FString Raw;
    if (!ReadSlot(Slot, Raw)) return Info;
    TSharedPtr<FJsonObject> Data;
    FString InkState;
    if (!FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Raw), Data) || !Data.IsValid() || !Data->TryGetStringField(TEXT("inkState"), InkState) || InkState.IsEmpty()) return Info;
    Info.bExists = true;
    FString SavedAt, Version;
    Data->TryGetStringField(TEXT("savedAt"), SavedAt);
    FDateTime::ParseIso8601(*SavedAt, Info.SavedAt);
    Data->TryGetStringField(TEXT("passage"), Info.Passage);
    Info.PassageTitle = Info.Passage;
    for (int32 i = 0; i < NarrativeBridgeStoryInfo::NumPassages; ++i)
        if (Info.Passage == NarrativeBridgeStoryInfo::Passages[i]) Info.PassageTitle = UNarrativeLocalization::Translate(NarrativeBridgeStoryInfo::PassageTitles[i]);
    Data->TryGetStringField(TEXT("excerpt"), Info.Excerpt);
    Data->TryGetStringField(TEXT("storyVersion"), Version);
    Info.bOtherVersion = Version != NarrativeBridgeStoryInfo::StoryVersion;
    return Info;
}

TArray<FNarrativeSlotInfo> UNarrativeBridgeComponent::GetSlots() const
{
    TArray<FNarrativeSlotInfo> Slots;
    for (int32 i = 0; i <= SaveSlots; ++i) Slots.Add(GetSlot(i));
    return Slots;
}

void UNarrativeBridgeComponent::QuickSave()
{
    if (!InkStory) return;
    WriteSlot(-1, SaveState());
    SetStatus(TEXT("Saved."));
}

bool UNarrativeBridgeComponent::QuickLoad()
{
    FString Data, Error;
    if (!ReadSlot(-1, Data)) { SetStatus(TEXT("There is no save yet.")); return false; }
    const bool bOk = TryLoadState(Data, Error);
    SetStatus(bOk ? (LoadNote.IsEmpty() ? FString(TEXT("Loaded.")) : LoadNote) : Error);
    return bOk;
}

void UNarrativeBridgeComponent::AutosaveIfNewPassage()
{
    // Only while the game plays (not in the editor's automation tests).
    const UWorld* World = GetWorld();
    if (!bAutosave || bSilent || !InkStory || !World || !World->IsGameWorld()) return;
    const FString Passage = GetCurrentPassage();
    if (Passage.IsEmpty() || Passage == AutosavedPassage) return;
    AutosavedPassage = Passage;
    SaveToSlot(AutosaveSlot);
}

void UNarrativeBridgeComponent::ReportError(const FString& Message)
{
    UE_LOG(LogTemp, Error, TEXT("[NarrativeBridge] %s"), *Message);
    SetStatus(Message);
    OnRuntimeError.Broadcast(Message);
}

void UNarrativeBridgeComponent::SetStatus(const FString& Message)
{
    Status = Message;
    OnStatusChanged.Broadcast(Status);
}

// ---- Text helpers ------------------------------------------------------------------------

FString UNarrativeBridgeComponent::PlainText(const FString& Text)
{
    static const TCHAR* EmphasisTags[] = { TEXT("<i>"), TEXT("</i>"), TEXT("<b>"), TEXT("</b>"), TEXT("<u>"), TEXT("</u>") };
    FString Out = Text;
    for (const TCHAR* Tag : EmphasisTags) Out.ReplaceInline(Tag, TEXT(""), ESearchCase::CaseSensitive);
    return Out;
}

FString UNarrativeBridgeComponent::RichText(const FString& Text)
{
    static const TCHAR* Closing[] = { TEXT("</i>"), TEXT("</b>"), TEXT("</u>") };
    FString Out = Text;
    for (const TCHAR* Tag : Closing) Out.ReplaceInline(Tag, TEXT("</>"), ESearchCase::CaseSensitive);
    return Out;
}

// ---- Pictures and sound ------------------------------------------------------------------

UTexture2D* UNarrativeBridgeComponent::LoadPicture(const FString& File)
{
    if (File.IsEmpty()) return nullptr;
    if (const TStrongObjectPtr<UTexture2D>* Cached = Pictures().Find(File)) return Cached->Get();
    TArray<uint8> Bytes;
    if (!FFileHelper::LoadFileToArray(Bytes, *(FPaths::ProjectContentDir() / NarrativeBridgeStoryInfo::ImageFolder / File), FILEREAD_Silent)) return nullptr;
    UTexture2D* Texture = FImageUtils::ImportBufferAsTexture2D(Bytes);
    if (!Texture) return nullptr;
    Pictures().Add(File, TStrongObjectPtr<UTexture2D>(Texture));
    return Texture;
}

FString UNarrativeBridgeComponent::PortraitFile(const FString& SpeakerId)
{
    for (int32 i = 0; i < NarrativeBridgeStoryInfo::NumPortraitSpeakers; ++i)
        if (SpeakerId == NarrativeBridgeStoryInfo::PortraitSpeakers[i]) return NarrativeBridgeStoryInfo::PortraitFiles[i];
    return FString();
}

UTexture2D* UNarrativeBridgeComponent::LoadPortrait(const FString& SpeakerId)
{
    return LoadPicture(PortraitFile(SpeakerId));
}

FString UNarrativeBridgeComponent::ClipAssetName(const FString& File)
{
    FString Name = FPaths::GetBaseFilename(File);
    for (TCHAR& Ch : Name)
        if (!FChar::IsAlnum(Ch) && Ch != TEXT('_')) Ch = TEXT('_');
    return Name;
}

USoundBase* UNarrativeBridgeComponent::LoadVoiceClip(const FString& File)
{
    if (File.IsEmpty()) return nullptr;
    const FString Name = ClipAssetName(File);
    const FString Path = FString(NarrativeBridgeStoryInfo::AudioPackagePath) + Name + TEXT(".") + Name;
    return LoadObject<USoundBase>(nullptr, *Path, nullptr, LOAD_NoWarn | LOAD_Quiet);
}

void UNarrativeBridgeComponent::ReleaseLoadedMedia()
{
    Pictures().Reset();
}

void UNarrativeBridgeComponent::QueueVoice(const FNarrativeLine& Line)
{
    if (!bPlayVoiceClips || Line.VoiceClip.IsEmpty() || !GetWorld()) return;
    if (USoundBase* Clip = LoadVoiceClip(Line.VoiceClip)) VoiceQueue.Add(Clip);
    else UE_LOG(LogTemp, Warning, TEXT("[NarrativeBridge] No voice clip %s in %s (import StorySource/VoiceClips)."), *Line.VoiceClip, NarrativeBridgeStoryInfo::AudioPackagePath);
}

void UNarrativeBridgeComponent::StopVoice()
{
    VoiceQueue.Reset();
    if (VoicePlaying) VoicePlaying->Stop();
    VoicePlaying = nullptr;
}

void UNarrativeBridgeComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
    // Voice clips play in order: the next when the last has finished.
    if (VoiceQueue.Num() == 0 || (VoicePlaying && VoicePlaying->IsPlaying())) return;
    USoundBase* Next = VoiceQueue[0];
    VoiceQueue.RemoveAt(0);
    VoicePlaying = Next ? UGameplayStatics::SpawnSound2D(this, Next, VoiceVolume * UNarrativeSettings::GetVoiceVolume()) : nullptr;
}
